WITH positioned AS (SELECT b.mktcode,b.tgtcode,b.bizdate,b.lastPx,MIN(b.lastPx/10000.0) OVER(PARTITION BY b.mktcode,b.tgtcode ORDER BY b.bizdate ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS hist_low,MAX(b.lastPx/10000.0) OVER(PARTITION BY b.mktcode,b.tgtcode ORDER BY b.bizdate ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS hist_high FROM `newzl`.`hsj_stock_hq_basic` b), candidates AS (SELECT p.mktcode,p.tgtcode,p.bizdate,e.ZJLXMainNetTur AS metric FROM positioned p JOIN `newzl`.`hsj_stock_hq_ext` e ON e.mktcode=p.mktcode AND e.tgtcode=p.tgtcode AND e.bizdate=p.bizdate WHERE p.mktcode=1 AND p.tgtcode BETWEEN '688000' AND '688999' AND p.bizdate='2026-04-14' AND e.maAngle=45 AND CASE WHEN p.lastPx/10000.0 IS NULL OR p.hist_low IS NULL OR p.hist_high IS NULL THEN NULL WHEN p.lastPx/10000.0<=p.hist_low THEN '最低' WHEN p.lastPx/10000.0>=p.hist_high THEN '最高' WHEN (p.lastPx/10000.0-p.hist_low)/NULLIF(p.hist_high-p.hist_low,0)<=0.25 THEN '低' WHEN (p.lastPx/10000.0-p.hist_low)/NULLIF(p.hist_high-p.hist_low,0)>=0.75 THEN '高' ELSE '中' END='低'), ranked AS (SELECT mktcode,tgtcode,bizdate,ROW_NUMBER() OVER(ORDER BY CASE WHEN metric IS NULL THEN 1 ELSE 0 END,metric ASC,mktcode ASC,tgtcode ASC) AS rn FROM candidates) SELECT mktcode,tgtcode,bizdate FROM ranked WHERE rn<=5;
